#!/usr/bin/env python3
"""Independently author the Hist Ia root question bank."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "questions/social"
LESSON = "lesson-social-content-hist-ia"
KG = "kg-social-content-hist-ia"
ITEMS = [
    ("明清中國、德川日本與朝鮮在十九世紀以前已有外交、貿易與文化往來。若要避免把東亞歷史寫成外力出現後才開始，哪項做法最恰當？", ["先畫出既有區域制度與交流網絡，再比較十九世紀軍事、貿易與外交壓力帶來的改變。", "把十九世紀以前都視為封閉，才能凸顯後來的外國影響。", "只記錄西方船艦與條約，其他東亞社會不必列入時間軸。", "只要出現改革，就可判定先前的政治秩序完全消失。"], "A", "連續性與變遷可以同時存在；比較前後的制度、網絡與回應，才能避免單線衝擊敘事。", "延續與變遷"),
    ("研究十九世紀東亞時，材料顯示某港口的外來船隻增加，但地方商人仍沿用舊有中介與信用關係。最合理的判讀是？", ["外來船隻增加後，舊有商業網絡必然全部失效。", "外來船隻與舊中介並存，顯示新的壓力可能被既有網絡吸收、調整或重新利用。", "只要港口仍有地方商人，就能證明沒有任何國際變化。", "港口材料可直接代表所有內陸地區的生活。"], "B", "新因素進入不等於舊網絡消失；需觀察哪些關係延續、哪些功能改變，以及證據範圍。", "區域網絡與調整"),
    ("比較清帝國、德川日本與朝鮮面對外來軍事和貿易壓力的資料時，哪一種比較最有歷史意識？", ["只找三地共同的結果，不必理會制度差異。", "以後來是否成功現代化作為唯一評分標準。", "先固定相同的時間範圍，再比較政權、財政、軍事與社會條件如何影響各自回應。", "把其中一地的改革方案當成其他地區的必然選擇。"], "C", "跨區比較必須控制時間和比較面向，並保留各地制度與社會條件，不能用單一結果倒推必然道路。", "多地比較"),
    ("一份外交文書強調維持傳統秩序，另一份商人帳冊卻顯示外來商品增加。面對兩者差異，第一步應是？", ["只相信外交文書，因為官方文字一定比交易記錄完整。", "只相信帳冊，因為經濟資料不會有立場。", "把兩份資料平均混合，直接寫成東亞全面開放。", "先核對兩份資料的形成目的、時間與記錄對象，再判斷它們是否描述不同層次的現象。"], "D", "官方秩序語言與實際交易可能位於不同層次；先辨識資料形成背景，才能解釋差異而非任意選邊。", "多重史料"),
    ("某地面對外來軍事威脅，政府增加軍費、地方士紳籌款，民眾則承擔徵稅與徵募。若只寫『國家改革成功』，最可能遺漏什麼？", ["改革所需的財政來源、地方協商與不同群體承擔的成本。", "外來勢力的存在本身。", "所有軍事技術的名稱。", "時間軸上的年份順序。"], "A", "政治回應不只是制度名稱，還包含資源來源、地方關係與成本分配；不同群體的經驗可能不一致。", "改革與社會成本"),
    ("一張東亞海域圖把航線、朝貢往來與私人貿易畫在同一張圖上。若研究者要判斷『區域互動』，應先做什麼？", ["把所有箭頭都視為同一種交流。", "只計算最長的航線，作為影響力排名。", "區分移動者、制度許可、商品與資訊，並標出地圖沒有呈現的群體與路徑。", "以現代國界重新命名所有古代節點。"], "C", "同一張圖中的航線可能代表不同制度和角色；把交流元素分層才能避免把朝貢、商貿與資訊流混為一談。", "海域網絡判讀"),
    ("研究者以『東方被動接受西方衝擊』解釋明治日本、清帝國與朝鮮的變化。哪項資料最能直接促使他修正這個框架？", ["三地都曾見到外國船艦。", "三地都有十九世紀的年份記錄。", "三地都使用過外來商品。", "各地在壓力出現前已有制度爭論、區域往來與改革選擇，且回應方向並不相同。"], "D", "若各地原有動態與回應不同，單一的外力—被動模型便不足以解釋延續與選擇。", "主動性與原有動態"),
    ("一份時間軸標出 1750 年的區域貿易、1839 年的戰爭、1850 年代的條約與 1890 年代的制度變革。要避免把事件串成單一路線，還應加入什麼？", ["只加入更多外國人物姓名。", "各時段的制度、社會群體與區域網絡如何延續或改變的證據。", "把所有年份改成同一種曆法而不說明轉換。", "刪除沒有戰爭的年份。"], "B", "時間順序只是骨架；必須補入制度和社會變化的機制，才能解釋事件之間不是自動因果。", "時間軸與機制"),
    ("某改革方案同時引進外來軍事技術與本地官僚制度調整，但地方文件顯示執行速度不一。最穩妥的結論是？", ["改革方案的提出就等於全國已完成改革。", "地方執行差異可忽略，因為中央政策才是真實歷史。", "改革是外來技術的直接複製，地方不會改造。", "方案、制度落地與地方反應是不同階段，需用不同資料判斷各階段的實際效果。"], "D", "政策文本、制度執行與地方經驗可能有落差；結論要明確指出所依據的階段和證據。", "政策與落地"),
    ("比較東亞各地的近代轉變時，研究者發現同樣面對貿易壓力，有的地方改革、有的地方限制、有的地方改以談判。哪項推論最合理？", ["不同回應可能反映政權結構、財政能力、社會利益與既有外交位置的差異，不能只用勇敢或保守評價。", "選擇限制的一方必然完全拒絕所有外來事物。", "選擇談判的一方必然沒有軍事壓力。", "改革速度最快的一方必然代表全部人民利益。"], "A", "回應差異需要放回制度、資源與社會條件分析，不能用單一價值標籤取代歷史解釋。", "回應選擇與條件"),
]
SOURCES = [
    {"url": "https://www.yacjh.kh.edu.tw/upload/221/101_30637/114%E4%B8%8B%E5%AD%B8%E6%9C%9F%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%AE%B5%E8%80%83%E4%B8%89%E5%B9%B4%E7%B4%9A%E7%9A%84%E7%A4%BE%E6%9C%83.pdf", "title": "高雄市立鹽埕國民中學公開段考社會科；僅研究時序、資料判讀與歷史推理題型，未複製原題。", "year": "114", "locator": "公開段考社會科 PDF；第 1 題至第 10 題型範圍：時序、資料判讀與因果界線", "observedPattern": "由制度、時序與多方材料要求學生提出證據範圍相稱的歷史解釋。"},
    {"url": "https://affairs.kh.edu.tw/1126/upload/file_list/149", "title": "高雄市立文府國民中學公開社會科試題入口；僅研究多資料互證題型，未複製原題。", "year": "113-114", "locator": "公開試題與解答入口；第 1 題至第 10 題型範圍：跨區交流、制度與多重證據", "observedPattern": "比較地圖、文字與角色材料，區分直接記錄、合理推論與待補證主張。"},
    {"url": "https://www.dwm.kh.edu.tw/view/index.php?MainMenuId=64182&MainType=0&SubMenuId=64184&SubType=104&WebID=344", "title": "高雄市立大灣國民中學公開段考試題入口；僅研究區域互動與多方觀點題型，未複製原題。", "year": "113-114", "locator": "公開段考試題入口；第 1 題至第 10 題型範圍：區域互動、文化變遷與多方角色", "observedPattern": "從區域材料分析不同角色、利益與變化，不以單一來源包辦結論。"},
]
def refs(): return [{**s, "subject": "social", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]
targets = ["A", "B", "C", "D", "A", "C", "D", "B", "D", "A"]
for i, (prompt, options, answer, reason, focus) in enumerate(ITEMS, 1):
    p = OUT / f"question-social-content-hist-ia-{i}.json"
    d = json.loads(p.read_text(encoding="utf-8")); assert d["lessonId"] == LESSON and d["knowledgeIds"] == [KG]
    target = targets[i - 1]; assert target == answer
    d["prompt"] = prompt; d["options"] = [{"id": chr(65+j), "text": x} for j, x in enumerate(options)]
    d["answer"] = {"value": answer, "explanation": f"本題聚焦「{focus}」。{reason} 正確答案為選項 {answer}：「{options[ord(answer)-65]}」。"}
    d["solutionStrategy"] = f"先用{focus}定位時間、角色、制度與證據，再區分延續、變化與尚待補證的推論；{reason}"
    d["solutionSteps"] = [f"讀題定位：圈出題目中的時段、地區、材料與任務，確認本題正在檢核「{focus}」。", "建立判準：把制度、網絡、社會群體與事件結果分層，並標記每個判斷的資料來源。", f"核對正解：選項 {answer}「{options[ord(answer)-65]}」符合題幹，因為{reason}", "逐項排除：檢查其餘選項是否把外力當成唯一原因、把政策文字當成全境實況，或把單一結果套用到所有地區。", "結論回查：重新核對年代、比較面向與證據強度；若加入新材料或改變尺度，必須重新建立結論。"]
    d["examPatternRefs"] = refs(); d["updatedAt"] = "2026-09-13"; d["reviewStatus"] = "draft"
    d["provenance"]["authoringNote"] = "依官方課綱、歷 Ia 知識圖譜及三所公立學校公開社會科試題的時序、區域互動與多方證據能力方向獨立改寫；未複製原題文字、選項、圖片或答案，待逐題學科與 Terra 複核。"
    p.write_text(json.dumps(d, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(ITEMS)} independent questions for {LESSON}")
